(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ru"] = {"ui":{"skip":"Перейти к содержимому","back":"← Назад к AI-gile","lang.button":"Язык: {name}","lang.dialog":"Выбери язык","lang.search":"Найти язык","lang.none":"Подходящих языков нет","lang.notYet":"{name} пока не переведён","theme.aria":"Переключить светлую и тёмную тему","theme.toLight":"Включить светлую тему","theme.toDark":"Включить тёмную тему","index.title":"AI-gile: твоя команда ИИ-разработчиков на одной доске","index.description":"AI-gile это канбан-доска для команд ИИ-программистов. Они работают, пока ты спишь, а тебе остаётся одна короткая стопка: что решить, что проверить и что принять.","hero.logoAlt":"Значок доски AI-gile","hero.h1.html":"Твоя команда ИИ-разработчиков на одной&nbsp;доске.","hero.alpha":"🐣 Закрытая пре-альфа","hero.alphaTitle":"Ещё сыро и не закончено: спасибо, что пробуешь!","hero.lede":"Они строят, пока ты спишь. Утром тебя ждёт одна короткая стопка: пара вопросов, пара вещей на проверку, один-два фиолетовых ромбика. Клик, принял, и обратно к кофе.","dl.windows":"Приложение для Windows","dl.browser":"Запустить в браузере","dl.soon":"Скоро","dl.notify":"🔔 Напиши, когда откроется","dl.notifySmall":"Альфа или бета","hero.secondary":"Agile, только команде не нужен кофе на стендапе. (Стендапы они всё равно проводят.)","pitch.h2":"AI-gile в любом количестве слов","pitch.lede":"Выбери длину: от одного слова до 144. Каждая длина это отдельное описание, написанное именно под неё. Двигай ползунок или жми стрелки.","pitch.rangeLabel":"Длина в словах","pitch.dice":"🎲 другой вариант","pitch.words.one":"{n} слово","pitch.words.few":"{n} слова","pitch.words.many":"{n} слов","pitch.words.other":"{n} слова","pitch.letters.one":"{n} буква","pitch.letters.few":"{n} буквы","pitch.letters.many":"{n} букв","pitch.letters.other":"{n} буквы","pitch.chars.one":"{n} символ","pitch.chars.few":"{n} символа","pitch.chars.many":"{n} символов","pitch.chars.other":"{n} символа","count.line.html.one":"{n} карточка на доске прямо сейчас","count.line.html.few":"{n} карточки на доске прямо сейчас","count.line.html.many":"{n} карточек на доске прямо сейчас","count.line.html.other":"{n} карточки на доске прямо сейчас","features.aria":"Что она делает","f.pile.h":"Одна стопка для тебя","f.pile.html":"<b>Тебе</b> собирает всё, что ждёт тебя, из всех проектов: вопросы, вещи на проверку, задачи, которые под силу только человеку. Твоя очередь подскажет, что дальше и сколько это займёт.","f.sleep.h":"Команды, которые работают, пока ты спишь","f.sleep.p":"У каждого проекта есть лид и команда ИИ-агентов. Оставь комментарий к карточке, команда проснётся, сделает работу и вернёт её с шагами, которые осилит даже уставший человек.","f.tester.h":"Сначала проверяет ИИ-тестировщик","f.tester.p":"Прежде чем что-то дойдёт до тебя, тестировщик проходит шаги в копии приложения и показывает, что увидел, со скриншотом. Пролистай прошедшее проверку и прими одним кликом.","f.proof.h":"Доказательства, а не обещания","f.proof.p":"Каждая сдача показывает, что изменилось: файлы, diff, скриншоты. Не нужно открывать каждое приложение, чтобы узнать, готово ли оно.","f.chat.h":"Общайся со своими лидами","f.chat.p":"Боковая панель как в Discord: по значку на проект, фиолетовые ромбики там, где нужен ты. Напиши лиду идею, и он превратит её в карточки и план, а тебе останется кнопка ✅ Go.","f.tidy.h":"Сама наводит порядок","f.tidy.p":"Похожие карточки сливаются в одну, запутанные названия исправляются, а проверка токенов следит, чтобы код не разбухал. Меньше переключений, меньше лишних мыслей.","f.private.h":"Твоя, на твоём компьютере","f.private.li1":"Доска работает на твоём компьютере и отвечает только тебе.","f.private.li2":"Личные сообщения между людьми защищены сквозным шифрованием.","f.private.li3":"Никаких аккаунтов, трекеров и cookie.","f.lang.h":"На твоём языке","f.lang.p":"Больше 120 языков: от нидерландского, валлийского и японского до пиратского, языка Йоды и клингонского, и быстрый переход на английский для слов разработчиков.","tl.aria":"Хронология от первого разговора до дорожной карты","tl.h2":"От первого разговора до того, что дальше","tl.lede":"Настоящие даты и время в твоём часовом поясе. После сегодняшнего дня идёт план, без обещанных дат.","tl.today":"Сегодня","tl.planned":"в планах","tl.cards.one":"{n} карточка","tl.cards.few":"{n} карточки","tl.cards.many":"{n} карточек","tl.cards.other":"{n} карточки","join.h2":"Присоединяйся","join.lede":"AI-gile строит один небольшой человек и множество терпеливых агентов. Пока всё закрыто: закрытая альфа для друзей. Хочешь попробовать, когда откроется?","join.btn":"Оставить заявку","join.small":"Напишем на почту, и больше ничего","footer.tag":"AI-gile. Без трекеров, без cookie, без кофе на стендапе.","footer.licence":"Лицензия для бизнеса","footer.status":"Статус","form.sending":"Отправляю…","form.failed":"Не вышло: попробуй позже.","form.offline":"Не удалось связаться с AI-gile: попробуй позже.","interest.title":"AI-gile: напиши мне, когда откроется альфа","interest.description":"Оставь почту, чтобы узнать, когда откроется закрытая альфа или бета AI-gile.","interest.h1":"🔔 Напиши, когда откроется","interest.lede":"AI-gile в закрытой пре-альфе. Оставь почту, и мы напишем один раз, когда для тебя найдётся место.","interest.email":"Твоя почта","interest.which":"Какой тест?","interest.alpha":"Закрытая альфа: рано, сыро, много изменений","interest.beta":"Бета: стабильнее, позже","interest.both":"Любой, что раньше","interest.submit":"Внесите меня в список","interest.thanks":"Спасибо! Ты в списке.","licence.title":"AI-gile: лицензия для бизнеса","licence.description":"Используешь AI-gile в бизнесе? Подай заявку на бесплатную лицензию.","licence.h1":"📜 Лицензия для бизнеса","licence.lede":"Используешь AI-gile на работе? Расскажи, кто ты и чем занимаешься. Если это приносит пользу, лицензия бесплатна.","licence.company":"Компания","licence.website":"Сайт","licence.what":"Чем занимаешься","licence.how":"Чем это помогает миру","licence.email":"Почта","licence.submit":"Отправить заявку","licence.thanks":"Спасибо! Ответим по почте.","status.title":"Статус AI-gile","status.h1":"Статус AI-gile","status.quiet":"Всё тихо","status.checking":"Проверяю…","status.offline":"Сейчас не получается связаться со службой статуса (пробую снова)","status.updated":"обновлено {ago}","status.justNow":"только что","status.min":"{n} мин назад","status.hours":"{n} ч назад","status.days":"{n} д назад","live.h2":"Смотрите, как это строится, в прямом эфире","live.caption":"Каждая карточка скрыта: вы видите форму работы, а не слова.","live.watching.one":"в эфире: смотрит {n}","live.watching.other":"в эфире: смотрят {n}","live.offline":"Живая доска немного отдыхает. Загляните позже.","live.cols":"Бэклог|К выполнению|В работе|Команда проверяет|Тебе на тест|Для команды|Готово","live.last.now":"Последняя карточка перемещена только что","live.last.min.one":"Последняя карточка перемещена {n} минуту назад","live.last.min.few":"Последняя карточка перемещена {n} минуты назад","live.last.min.many":"Последняя карточка перемещена {n} минут назад","live.last.min.other":"Последняя карточка перемещена {n} минуты назад","live.last.hour.one":"Последняя карточка перемещена {n} час назад","live.last.hour.few":"Последняя карточка перемещена {n} часа назад","live.last.hour.many":"Последняя карточка перемещена {n} часов назад","live.last.hour.other":"Последняя карточка перемещена {n} часа назад","live.last.day.one":"Последняя карточка перемещена {n} день назад","live.last.day.few":"Последняя карточка перемещена {n} дня назад","live.last.day.many":"Последняя карточка перемещена {n} дней назад","live.last.day.other":"Последняя карточка перемещена {n} дня назад"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботы.","Делегировано."]},{"n":2,"texts":["Канбан роботов.","Агенты, организованные.","Идеи воплощены."]},{"n":3,"texts":["Канбан для роботов.","Идеи становятся функциями.","Бесплатный канбан агентов."]},{"n":5,"texts":["Канбан-доска, которой управляют агенты.","Ты пишешь карточки. Агенты строят.","Бесплатно, локально, проверено, чуть нелепо."]},{"n":8,"texts":["Бесплатная канбан-доска на твоём компьютере, где работают ИИ-агенты.","Напиши идею. Агенты построят. Ты примешь.","Agile для одного человека и многих терпеливых роботов."]},{"n":13,"texts":["Канбан-доска на твоём компьютере, где карточки берут в работу ИИ-агенты.","Напиши идею. Целая команда агентов её построит. Потом тестировщик всё проверит, и ты принимаешь.","Бесплатно, без аккаунтов и трекеров: доска, пара роботов и ты за главного."]},{"n":21,"texts":["AI-gile это канбан-доска для работы с ИИ-агентами, которые пишут код. Они берут карточки, а ты проверяешь и принимаешь результат.","У каждого проекта есть лид и команда ИИ-агентов. Оставь комментарий к любой карточке, и команда берётся за дело.","Бесплатный личный список дел, который работает на твоём компьютере. Работают роботы. А говорит «да» только один человек: ты."]},{"n":34,"texts":["Ты кладёшь идеи на доску. Команда ИИ-агентов превращает их в работающие функции, проверяет и возвращает тебе с шагами для пробы. Пока ты не скажешь «готово», ничто не считается готовым.","AI-gile это самодельная канбан-доска, которую Рич построил с огромной помощью агентов, которыми она теперь и управляет. Она бесплатна, работает на твоём компьютере и достаётся друзьям, а не продаётся.","Представь обычную канбан-доску с колонками от бэклога до «Готово», только карточки здесь берут ИИ-агенты. Они докладывают о ходе работы, задают вопросы, когда застряли, и всегда ждут твоего одобрения."]},{"n":55,"texts":["AI-gile это канбан-доска, где команда состоит из ИИ-агентов. У каждого проекта есть лид, который планирует работу, и помощники, которые её делают. Когда функция готова, ИИ-тестировщик пробует её и делает скриншот, а потом она попадает в твою стопку. Ты принимаешь её или оставляешь комментарий, и агенты переделывают.","Всё началось с того, что один человек пытался уследить сразу за множеством сеансов ИИ-программирования, и это выросло в настоящую доску. Она работает на твоём компьютере, не требует аккаунта и не ставит трекеры. Бесплатна для друзей и всех любопытных. Она ещё и недоделана, так что жди шероховатостей и сюрпризов.","Вот честная версия. Идеи по-прежнему придумываешь ты, и результат по-прежнему проверяешь ты. А AI-gile делает всё, что между ними: держит карточки в порядке, будит нужного агента, когда ты комментируешь, показывает, что именно изменилось, и собирает всё это в одну короткую стопку для тебя. Никакой магии, просто аккуратная работа, которую больше не нужно делать руками."]},{"n":89,"texts":["AI-gile это бесплатная канбан-доска, которая работает на твоём собственном компьютере. Вместо людей у каждого проекта команда ИИ-агентов: лид, который превращает твои идеи в карточки и план, и помощники, которые берут карточки по порядку важности. Когда что-то построено, ИИ-тестировщик проходит шаги проверки и показывает, что увидел. Потом результат ждёт в одной стопке под названием «Тебе». Ты принимаешь его или оставляешь комментарий, и команда пробует ещё раз. До «Готово» ничто не доходит без тебя.","Есть и неожиданные возможности. Ночной дозор пополняет колонку «К выполнению», пока ты спишь, и выбирает карточки, на которые не нужен твой ответ. Счётчик токенов показывает, сколько агенты израсходовали сегодня и за неделю, а режим без токенов велит им прекратить траты. Можно переписываться с друзьями, а личные сообщения защищены сквозным шифрованием. Доска говорит примерно на 120 языках, включая нидерландский, фламандский, пиратский и клингонский. Ничто из этого не стоит ни копейки, и никто не пытается тебе это продать.","AI-gile это небольшой личный проект, а не компания. Рич хотел присматривать за несколькими проектами с ИИ-программированием, не открывая каждое приложение, и вместе с агентами построил для этого доску, а затем с её помощью достроил всё остальное. Сейчас это закрытая пре-альфа: по большей части работает, но только у горстки друзей. Здесь нет страницы с ценами, рассылки и плана роста. Если звучит полезно, попроси попробовать, когда доступ чуть расширится. Сейчас она держится на терпении агентов и на отзывах друзей. Каждый отзыв превращается в карточку, а карточка рано или поздно превращается в готовую функцию."]},{"n":144,"texts":["AI-gile это канбан-доска для одного человека и множества ИИ-агентов. Она работает на твоём собственном компьютере и совершенно бесплатна. Ты добавляешь проекты, и у каждого проекта появляются лид и небольшая команда. Ты общаешься с лидом, как в Discord, и описываешь идею; лид превращает её в карточки и план, а потом ждёт, пока ты нажмёшь Go. Команда проходит по карточкам в порядке важности, пользуясь простой командной строкой, сделанной для языковых моделей. Прежде чем что-либо вернётся к тебе, ИИ-тестировщик проходит шаги в копии приложения и прикладывает скриншот. Готовая работа попадает в твою стопку вместе с изменёнными файлами и diff. Ты принимаешь её или оставляешь комментарий, и команда просыпается и пробует снова. Переместить карточку в «Готово» можешь только ты.","День с AI-gile выглядит примерно так. Вечером ты оставляешь несколько комментариев: эта кнопка не на месте, тот список надо отсортировать, а нельзя ли тёмную тему. И идёшь спать. Агенты читают комментарии, вносят правки, проверяют их и возвращают тебе. Если «К выполнению» пустеет, ночной дозор наполняет колонку из бэклога карточками, на которые не нужен твой ответ. Утром тебя ждёт одна короткая стопка: пара вопросов и несколько вещей на пробу, к каждой шаги, которые осилит сонный человек, и скриншот, где всё работает. Ты пролистываешь, принимаешь хорошее и возвращаешь остальное. Если что-то не понравилось, пишешь комментарий, и цикл начинается заново, без совещаний и без обид. Лид следит, чтобы работа шла по порядку, а скрам-мастер напоминает застрявшим карточкам, что они застряли. Счётчик токенов показывает расход, а режим без токенов выручает в скромные недели. Потом ты завтракаешь, а с этим агенты пока не помогут.","Сначала о том, чем AI-gile не является. Это не стартап, не товар на продажу, и никто не собирает твои данные. Это бесплатная доска, которая работает на твоём компьютере, без аккаунтов, трекеров и cookie. А вот что это такое: одно аккуратное место, где видны все проекты с ИИ-программированием сразу, где карточки делает команда агентов, а решения принимаешь ты. Она объединяет похожие карточки, исправляет запутанные названия и следит, чтобы код оставался лёгким. Она говорит примерно на 120 языках, от нидерландского и фламандского до пиратского и клингонского. Друзья могут переписываться друг с другом приватно и с шифрованием. Её построили Рич и множество терпеливых агентов, по большей части пользуясь ею же. Это закрытая пре-альфа, так что местами шероховато. Если звучит весело, попроси вежливо, и, возможно, попадёшь раньше других."]}],"quips":{"1":"Одно слово. Смело. Возможно, слишком смело.","3":"Три слова. Уже честнее большинства страниц о продуктах.","8":"Восемь слов. Всё ещё короче стендапа.","21":"Кстати, длины это story points. Конечно же.","55":"Пятьдесят пять слов. Пока ты читал, две карточки успели завершиться.","144":"Это самый длинный вариант. Варианта 233 нет. Агенты ушли спать."}},"timeline":{"first-idea.name":"Первая идея","first-idea.line":"Самый первый разговор, когда кода ещё не было.","first-board.name":"Первая доска","first-board.line":"Доска, которая следит за собственной разработкой: карточки, колонки, перетаскивание, проекты.","team-roles.name":"Команда и роли","team-roles.line":"Профили агентов, шаблоны команд, пространства и кто чем занят.","install.name":"Установка и релизы","install.line":"Архив, который друг сможет установить, самообновление, каналы и откат.","usage-saver.name":"Экономия расхода","usage-saver.line":"Измерять стоимость запусков, держать код лёгким, беречь лимит.","friends.name":"Друзья и общий доступ","friends.line":"Личные сообщения, зашифрованный ретранслятор, приглашения, роли и общие проекты.","languages.name":"Языки","languages.line":"Каждый текст на экране в языковом файле, сначала нидерландский и фламандский.","ai-tester.name":"ИИ-тестировщик","ai-tester.line":"Тестировщик первым проверяет каждую сдачу и показывает, что увидел.","website.name":"Сайт","website.line":"aigile.lol, тизер и эта хронология.","streaming.name":"Чат и стриминг","streaming.line":"Discord, Twitch, OBS, режим стримера, гифки и эмодзи.","no-ai.name":"Версия без ИИ","no-ai.line":"Доска для тех, кто пишет код без ИИ, и публичные доски.","night-watch.name":"Ночной дозор","night-watch.line":"Сторож и скрам-мастер держат команды в работе, пока ты спишь.","p-more.name":"Всё остальное","p-more.line":"Идеи поменьше, которые ждут своей очереди.","p-android.name":"Телефон и Android","p-android.line":"Доступ к доске с телефона, а потом и родное приложение для Android.","p-release.name":"Альфа и дальше","p-release.line":"Закрытая альфа, живой сайт, затем бета.","p-languages.name":"Ещё языки","p-languages.line":"Больше сотни языков и режим погружения для тех, кто учит язык.","p-engines.name":"Ещё ИИ-движки","p-engines.line":"Выбирай Claude, Codex или Gemini для каждого агента.","p-pro.name":"Профессиональная практика","p-pro.line":"Метки риска, барьеры слияния, карточки инцидентов и ограждения.","p-self.name":"Забота о тебе","p-self.line":"Режим усталости, напоминания о заботе о себе и 4:20.","p-servers.name":"Серверы и масштаб","p-servers.line":"Общие настройки сервера, роли и планы на рост.","p-livestream.name":"Дополнения для стриминга","p-livestream.line":"Чат Twitch, свои эмодзи и публичный просмотр вживую."}};
